/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect, useState, useMemo } from 'react';
import { client, useConfig, useElementData, useElementColumns, useVariable, useActionTrigger } from '@sigmacomputing/plugin';
import { Button } from './components/ui/button';
import { Settings as SettingsIcon } from 'lucide-react';
import Settings, { DEFAULT_SETTINGS } from './Settings';
import { processGanttData, describeSkipped } from './utils/dataProcessor';
import { toDateString } from './utils/dates';
import GanttChart from './GanttChart';
import HelpModal from './HelpModal';
import Onboarding from './Onboarding';
import './index.css';

// Configure the plugin editor panel
client.config.configureEditorPanel([
  { name: 'source', type: 'element' },
  { name: 'taskName', type: 'column', source: 'source', allowMultiple: false, label: 'Task Name' },
  { name: 'startDate', type: 'column', source: 'source', allowMultiple: false, allowedTypes: ['datetime'], label: 'Start Date' },
  { name: 'endDate', type: 'column', source: 'source', allowMultiple: false, allowedTypes: ['datetime'], label: 'End Date' },
  { name: 'status', type: 'column', source: 'source', allowMultiple: false, label: 'Status (Optional)' },
  { name: 'stage', type: 'column', source: 'source', allowMultiple: false, label: 'Release Stage (Optional)' },
  { name: 'groupBy', type: 'column', source: 'source', allowMultiple: false, label: 'Group Rows By, e.g. Team (Optional)' },
  { name: 'ID', type: 'column', source: 'source', allowMultiple: false, label: 'ID Column (Optional)' },
  { name: 'keyColumns', type: 'column', source: 'source', allowMultiple: true, label: 'Key Columns to build ID, e.g. Team, Project, Stage (Optional)' },
  { name: 'dependencies', type: 'column', source: 'source', allowMultiple: false, label: 'Has Dependency On (Optional)' },
  { name: 'blockedBy', type: 'column', source: 'source', allowMultiple: false, label: 'Blocked By (Optional)' },
  { name: 'assignee', type: 'column', source: 'source', allowMultiple: false, label: 'Owner (Optional)' },
  { name: 'progress', type: 'column', source: 'source', allowMultiple: false, label: 'Progress 0-100 (Optional)' },
  { name: 'parentTask', type: 'column', source: 'source', allowMultiple: false, label: 'Parent Task Name (Optional)' },
  { name: 'details', type: 'column', source: 'source', allowMultiple: false, label: 'Details (Optional)' },
  { name: 'selectedTaskId', type: 'variable', label: 'Selected ID Control' },
  { name: 'selectedTaskName', type: 'variable', label: 'Selected Name Control' },
  { name: 'selectedStartDate', type: 'variable', label: 'Start Date Control' },
  { name: 'selectedEndDate', type: 'variable', label: 'End Date Control' },
  { name: 'config', type: 'text', label: 'Settings Config (JSON)', defaultValue: '{}' },
  { name: 'editMode', type: 'toggle', label: 'Edit Mode' },
  { name: 'updateTask', type: 'action-trigger', label: 'Update Task' },
  { name: 'openTaskModal', type: 'action-trigger', label: 'Open Task Modal' }
]);

function App() {
  const config = useConfig();
  const sigmaData = useElementData(config.source);
  const elementColumns = useElementColumns(config.source);
  const [error, setError] = useState(null);
  const [showSettings, setShowSettings] = useState(false);
  const [settings, setSettings] = useState(DEFAULT_SETTINGS);
  const [showHelp, setShowHelp] = useState(false);
  // Add state for optimistic updates
  const [pendingUpdates, setPendingUpdates] = useState(new Map());

  // Get variables
  const [, setTaskIdVariable] = useVariable(config.selectedTaskId);
  const [, setTaskNameVariable] = useVariable(config.selectedTaskName);
  const [, setStartDateVariable] = useVariable(config.selectedStartDate);
  const [, setEndDateVariable] = useVariable(config.selectedEndDate);
  const triggerUpdateTask = useActionTrigger(config.updateTask);
  const triggerOpenTaskModal = useActionTrigger(config.openTaskModal);

  // Parse config JSON and load settings
  useEffect(() => {
    if (config.config && config.config.trim()) {
      try {
        const parsedConfig = JSON.parse(config.config);
        const newSettings = { ...DEFAULT_SETTINGS, ...parsedConfig };
        setSettings(newSettings);
      } catch (err) {
        setSettings(DEFAULT_SETTINGS);
      }
    } else {
      setSettings(DEFAULT_SETTINGS);
    }
  }, [config.config]);

  // Apply styling theme globally whenever settings change
  useEffect(() => {
    const customColors = settings?.styling?.customColors;
    if (customColors && typeof customColors === 'object') {
      Object.entries(customColors).forEach(([property, value]) => {
        try {
          document.documentElement.style.setProperty(property, value);
        } catch (_) {
          // ignore
        }
      });
    }
  }, [settings?.styling]);

  // Clear old pending updates when sigmaData changes (data has been updated by Sigma)
  useEffect(() => {
    if (sigmaData && pendingUpdates.size > 0) {
      // Clear updates that are older than 5 seconds or when data changes
      const now = Date.now();
      setPendingUpdates(prev => {
        const newUpdates = new Map();
        for (const [key, value] of prev) {
          // Keep updates that are less than 5 seconds old
          if (now - value.timestamp < 5000) {
            newUpdates.set(key, value);
          }
        }
        return newUpdates;
      });
    }
  }, [sigmaData, pendingUpdates.size]);

  // Additional cleanup timer for pending updates
  useEffect(() => {
    const interval = setInterval(() => {
      if (pendingUpdates.size > 0) {
        const now = Date.now();
        setPendingUpdates(prev => {
          const newUpdates = new Map();
          for (const [key, value] of prev) {
            // Keep updates that are less than 10 seconds old
            if (now - value.timestamp < 10000) {
              newUpdates.set(key, value);
            }
          }
          return newUpdates;
        });
      }
    }, 5000); // Check every 5 seconds

    return () => clearInterval(interval);
  }, [pendingUpdates.size]);

  // Process gantt data with column information and apply optimistic updates
  const ganttData = processGanttData(sigmaData, config, settings, elementColumns);
  
  // Apply pending updates for optimistic UI
  const ganttDataWithOptimisticUpdates = useMemo(() => {
    if (!ganttData || pendingUpdates.size === 0) {
      return ganttData;
    }

    return {
      ...ganttData,
      tasks: ganttData.tasks.map(task => {
        const pendingUpdate = pendingUpdates.get(task.rowId);
        if (pendingUpdate) {
          return {
            ...task,
            start: pendingUpdate.startDate || task.start,
            end: pendingUpdate.endDate || task.end
          };
        }
        return task;
      })
    };
  }, [ganttData, pendingUpdates]);

  const handleSettingsSave = (newSettings) => {
    setSettings(newSettings);
    setShowSettings(false);
  };

  const handleTaskClick = async (task) => {
    if (task.isGroup) return; // group rows are synthetic, not records
    try {
      // Set variables for the selected task
      if (config.selectedTaskId && task.rowId !== undefined) {
        await setTaskIdVariable(task.recordId ?? task.rowId);
      }
      
      if (config.selectedTaskName && task.name) {
        await setTaskNameVariable(task.fullName ?? task.name);
      }
      
      if (config.selectedStartDate && task.start) {
        let startDateString;
        if (task.start instanceof Date) {
          startDateString = task.start.toISOString();
        } else if (typeof task.start === 'string') {
          startDateString = task.start;
        } else {
          startDateString = String(task.start);
        }
        try {
          // Set as YYYY-MM-DD string format
          const startDate = new Date(startDateString);
          const startDateFormatted = toDateString(startDate); // "2025-07-18"
          await setStartDateVariable(startDateFormatted);
        } catch (error) {
          // Error handling without console logging
        }
      }
      
      if (config.selectedEndDate && task.end) {
        let endDateString;
        if (task.end instanceof Date) {
          endDateString = task.end.toISOString();
        } else if (typeof task.end === 'string') {
          endDateString = task.end;
        } else {
          endDateString = String(task.end);
        }
        try {
          // Set as YYYY-MM-DD string format
          const endDate = new Date(endDateString);
          const endDateFormatted = toDateString(endDate); // "2025-07-18"
          await setEndDateVariable(endDateFormatted);
        } catch (error) {
          // Error handling without console logging
        }
      }

      // Optionally trigger the configured modal action on task click
      if (settings?.openModalOnTaskClick && triggerOpenTaskModal) {
        try {
          await triggerOpenTaskModal();
        } catch (error) {
          // Error handling without console logging
        }
      }
    } catch (error) {
      setError(`Failed to select task: ${error.message}`);
    }
  };

  const handleDateChange = async (task, newStartDate, newEndDate) => {
    // Only rows with real date columns can be rescheduled
    if (task.isGroup) return;
    try {
      // Normalize the new dates
      let normalizedStartDate = null;
      let normalizedEndDate = null;

      // Handle start date normalization
      if (newStartDate instanceof Date) {
        normalizedStartDate = newStartDate;
      } else if (typeof newStartDate === 'string') {
        normalizedStartDate = new Date(newStartDate);
      } else if (Array.isArray(newStartDate) && newStartDate.length > 0) {
        const firstDate = newStartDate[0];
        if (firstDate instanceof Date) {
          normalizedStartDate = firstDate;
        } else {
          normalizedStartDate = new Date(String(firstDate));
        }
      } else if (task.start) {
        normalizedStartDate = task.start instanceof Date ? task.start : new Date(task.start);
      }

      // Handle end date normalization
      if (newEndDate instanceof Date) {
        normalizedEndDate = newEndDate;
      } else if (typeof newEndDate === 'string') {
        normalizedEndDate = new Date(newEndDate);
      } else if (Array.isArray(newEndDate) && newEndDate.length > 0) {
        const firstDate = newEndDate[0];
        if (firstDate instanceof Date) {
          normalizedEndDate = firstDate;
        } else {
          normalizedEndDate = new Date(String(firstDate));
        }
      } else if (task.end) {
        normalizedEndDate = task.end instanceof Date ? task.end : new Date(task.end);
      }

      // Store optimistic update immediately for smooth UI
      if (normalizedStartDate || normalizedEndDate) {
        setPendingUpdates(prev => {
          const newUpdates = new Map(prev);
          newUpdates.set(task.rowId, {
            startDate: normalizedStartDate,
            endDate: normalizedEndDate,
            timestamp: Date.now()
          });
          return newUpdates;
        });
      }

      // Set all variables for the task update
      if (config.selectedTaskId && task.rowId !== undefined) {
        try {
          await setTaskIdVariable(task.recordId ?? task.rowId);
        } catch (error) {
          // Error handling without console logging
        }
      }
      
      if (config.selectedTaskName && task.name) {
        try {
          await setTaskNameVariable(task.fullName ?? task.name);
        } catch (error) {
          // Error handling without console logging
        }
      }
      
      // Handle start date - use task's current start date if newStartDate is invalid
      if (config.selectedStartDate && normalizedStartDate) {
        try {
          // Set as YYYY-MM-DD string format
          const startDateFormatted = toDateString(normalizedStartDate); // "2025-07-18"
          await setStartDateVariable(startDateFormatted);
        } catch (error) {
          // Error handling without console logging
        }
      }
      
      // Handle end date - use task's current end date if newEndDate is invalid
      if (config.selectedEndDate && normalizedEndDate) {
        try {
          // Set as YYYY-MM-DD string format
          const endDateFormatted = toDateString(normalizedEndDate); // "2025-07-18"
          await setEndDateVariable(endDateFormatted);
        } catch (error) {
          // Error handling without console logging
        }
      }
      
      // Trigger the update action - RE-ENABLED
      if (triggerUpdateTask) {
        await triggerUpdateTask();
      }
      
    } catch (error) {
      setError(`Failed to update task dates: ${error.message}`);
      
      // Remove the optimistic update if there was an error
      setPendingUpdates(prev => {
        const newUpdates = new Map(prev);
        newUpdates.delete(task.rowId);
        return newUpdates;
      });
    }
  };

  const handleTaskSelect = async (task, isSelected) => {
    // Selection does not automatically trigger click behaviors
  };

  const handleExpanderClick = (task) => {
    // Handle hierarchy expansion if needed
  };

  if (error) {
    return (
      <div className="min-h-screen bg-background text-foreground flex items-center justify-center p-10">
        <div className="text-center max-w-md space-y-4">
          <div className="rounded-lg border border-destructive/50 bg-destructive/10 p-6">
            <h3 className="text-lg font-semibold text-destructive mb-2">Error</h3>
            <p className="text-muted-foreground">{error}</p>
          </div>
        </div>
      </div>
    );
  }

  if (!config.source || !config.taskName || !config.startDate || !config.endDate) {
    return (
      <>
        <Onboarding
          hasSource={!!config.source}
          hasRequiredColumns={!!(config.taskName && config.startDate && config.endDate)}
          editMode={!!config.editMode}
          onOpenSettings={() => setShowSettings(true)}
          onOpenHelp={() => setShowHelp(true)}
        />
        <Settings
          isOpen={showSettings}
          onClose={() => setShowSettings(false)}
          currentSettings={settings}
          onSave={handleSettingsSave}
          client={client}
          elementColumns={elementColumns}
          config={config}
        />
        <HelpModal isOpen={showHelp} onClose={() => setShowHelp(false)} />
      </>
    );
  }

  if (!sigmaData || !ganttDataWithOptimisticUpdates) {
    return null; // Config is set; while data loads, show nothing
  }

  return (
    <div className="min-h-screen h-screen flex flex-col bg-background text-foreground relative">
      {config.editMode && (
        <Button 
          className="absolute top-5 right-5 z-10 gap-2"
          onClick={() => setShowSettings(true)}
          size="sm"
          variant="default"
        >
          <SettingsIcon className="h-4 w-4" />
          Settings
        </Button>
      )}
      
      <div className="flex-1 min-h-0 rounded-lg border bg-background">
        <GanttChart 
          data={ganttDataWithOptimisticUpdates}
          settings={settings}
          onTaskClick={handleTaskClick}
          onTaskSelect={handleTaskSelect}
          onExpanderClick={handleExpanderClick}
          onDateChange={handleDateChange}
        />
      </div>
      {ganttDataWithOptimisticUpdates.tasks.length > 0 && describeSkipped(ganttDataWithOptimisticUpdates.skipped) && (
        <div className="px-3 py-1.5 text-xs text-muted-foreground">
          {describeSkipped(ganttDataWithOptimisticUpdates.skipped)}
        </div>
      )}
      
      <Settings
        isOpen={showSettings}
        onClose={() => setShowSettings(false)}
        currentSettings={settings}
        onSave={handleSettingsSave}
        client={client}
        elementColumns={elementColumns}
        config={config}
      />
      <HelpModal isOpen={showHelp} onClose={() => setShowHelp(false)} />
    </div>
  );
}

export default App; 