/**
 * Roadmap helpers: roadmap status normalization, stage progress, and
 * dependency-key resolution.
 *
 * These exist because product-roadmap rows use numbered statuses
 * ("1- On Track", "6- Blocked") and identify each other by a composite key
 * (Team · Project · Stage) rather than a row id.
 */

/**
 * Status vocabulary. Roadmap statuses are matched by their leading number
 * ("1- On Track", "4.5 Delayed for Escalation" -> 4); plain words are matched
 * as a fallback so the plugin still works on generic task data.
 */
export const STATUS_META = {
  on_track:    { label: 'On track',    color: '#16a34a', rank: 3, done: false, inactive: false },
  new:         { label: 'New',         color: '#2563eb', rank: 4, done: false, inactive: false },
  done:        { label: 'Done',        color: '#475569', rank: 7, done: true,  inactive: false },
  delayed:     { label: 'Delayed',     color: '#d97706', rank: 2, done: false, inactive: false },
  dropped:     { label: 'Dropped',     color: '#cbd5e1', rank: 9, done: false, inactive: true },
  blocked:     { label: 'Blocked',     color: '#dc2626', rank: 1, done: false, inactive: false },
  not_started: { label: 'Not started', color: '#94a3b8', rank: 5, done: false, inactive: false },
  paused:      { label: 'Paused',      color: '#cbd5e1', rank: 8, done: false, inactive: true },
  in_progress: { label: 'In progress', color: '#2563eb', rank: 3, done: false, inactive: false },
  unknown:     { label: 'No status',   color: '#cbd5e1', rank: 6, done: false, inactive: false }
};

const NUMBER_TO_KEY = { 1: 'on_track', 2: 'new', 3: 'done', 4: 'delayed', 5: 'dropped', 6: 'blocked', 7: 'not_started', 8: 'paused' };

export function normalizeStatus(raw, settings = {}) {
  const text = raw === null || raw === undefined ? '' : String(raw).trim();
  let key = 'unknown';
  const num = text.match(/^\s*(\d)/);
  if (num && NUMBER_TO_KEY[num[1]]) {
    key = NUMBER_TO_KEY[num[1]];
  } else {
    const t = text.toLowerCase();
    if (t.includes('block')) key = 'blocked';
    else if (t.includes('delay') || t.includes('at risk')) key = 'delayed';
    else if (t.includes('complete') || t === 'done') key = 'done';
    else if (t.includes('on track')) key = 'on_track';
    else if (t.includes('in progress')) key = 'in_progress';
    else if (t.includes('not started')) key = 'not_started';
    else if (t.includes('drop')) key = 'dropped';
    else if (t.includes('pause')) key = 'paused';
    else if (t === 'new') key = 'new';
  }
  const overrides = (settings.statusColors && settings.statusColors[key]) || null;
  const meta = STATUS_META[key];
  return {
    key,
    raw: text,
    label: text || meta.label,
    shortLabel: meta.label,
    color: overrides || meta.color,
    rank: meta.rank,
    done: meta.done,
    inactive: meta.inactive
  };
}

/** Stage -> progress percent along the configured stage order. */
export function stageProgress(stage, stageOrder) {
  if (!stage || !Array.isArray(stageOrder) || stageOrder.length === 0) return null;
  const s = String(stage).trim().toLowerCase();
  const idx = stageOrder.findIndex(x => String(x).trim().toLowerCase() === s);
  if (idx < 0) return null;
  return Math.round(((idx + 1) / stageOrder.length) * 100);
}

/**
 * Split a dependency cell into ids, resolving against the known id set.
 * 'auto': a JSON array, else the whole value if it is a known id, else split
 * on "|" then ";" then ",". This keeps keys like
 * "Infra · MySQL Upgrade / Maintenance, Savings · Internal" intact.
 */
export function resolveDependencyIds(value, knownIds, delimiter = 'auto') {
  if (value === null || value === undefined || value === '') return [];
  if (Array.isArray(value)) return value.map(v => String(v).trim()).filter(Boolean);
  const text = String(value).trim();
  if (!text) return [];
  if (text.startsWith('[')) {
    try {
      const parsed = JSON.parse(text);
      if (Array.isArray(parsed)) return parsed.map(v => String(v).trim()).filter(Boolean);
    } catch (_) { /* fall through */ }
  }
  if (delimiter !== 'auto') {
    return text.split(delimiter).map(v => v.trim()).filter(Boolean);
  }
  if (knownIds.has(text)) return [text];
  for (const sep of ['|', ';', ',']) {
    if (text.includes(sep)) return text.split(sep).map(v => v.trim()).filter(Boolean);
  }
  return [text];
}
