import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { Gantt, ViewMode } from 'gantt-task-react';
import 'gantt-task-react/dist/index.css';
import { getTaskColor } from './utils/dataProcessor';
import { snapToDay } from './utils/dates';
import { pixelsPerDay, fitBarLabel, makeTextMeasurer } from './utils/labels';
import { format, isValid as isValidDate } from 'date-fns';

const GanttChart = ({ 
  data, 
  settings, 
  onTaskClick, 
  onTaskSelect,
  onExpanderClick,
  onDateChange
}) => {
  const [view, setView] = useState(settings?.defaultViewMode || ViewMode.Month);
  const [selectedTask, setSelectedTask] = useState(null);
  const [expandedTasks, setExpandedTasks] = useState(new Set());
  const containerRef = useRef(null);
  const [availableHeight, setAvailableHeight] = useState(null);
  const calendarMutationObserverRef = useRef(null);
  const lastDragTimeRef = useRef(0);
  const lastDateChangeRef = useRef({ key: '', time: 0 });

  // Dynamically size the chart to fill the viewport/container height
  useEffect(() => {
    const updateHeights = () => {
      if (!containerRef.current) return;
      const containerHeight = containerRef.current.clientHeight || 0;
      const computed = Math.max(containerHeight, 200);
      setAvailableHeight(computed);
    };

    updateHeights();

    const resizeObserver = new ResizeObserver(updateHeights);
    if (containerRef.current) {
      resizeObserver.observe(containerRef.current);
    }
    window.addEventListener('resize', updateHeights);
    return () => {
      resizeObserver.disconnect();
      window.removeEventListener('resize', updateHeights);
    };
  }, []);

  // Keep view mode in sync with settings (date aggregation from Settings)
  useEffect(() => {
    if (settings?.defaultViewMode && settings.defaultViewMode !== view) {
      setView(settings.defaultViewMode);
    }
  }, [settings?.defaultViewMode, view]);

  // Post-process calendar header to replace weekday with month name on 1st of month
  const updateCalendarHeaderLabels = useCallback(() => {
    try {
      if (!containerRef.current) return;
      if (view !== ViewMode.Day) return; // Only apply in Day view

      const calendarGroup = containerRef.current.querySelector('svg .calendar');
      if (!calendarGroup) return;

      // Gather month labels from hidden top row
      const monthNodes = Array.from(calendarGroup.querySelectorAll('.calendarTop text'));
      const months = monthNodes.map((n) => ({
        x: Number(n.getAttribute('x')) || 0,
        name: (n.textContent || '').trim()
      })).filter(m => m.name);

      if (months.length === 0) return;

      // Update bottom labels for day 1 -> "Mon, 1" => "May 1" and make them bold
      const bottomNodes = Array.from(calendarGroup.querySelectorAll('text')).filter(n => !n.closest('.calendarTop'));
      bottomNodes.forEach((node) => {
        const raw = (node.textContent || '').trim();
        let isFirstOfMonth = false;
        let dayNum = NaN;

        if (raw.includes(',')) {
          const parts = raw.split(',');
          const dayStr = (parts[1] || '').trim();
          dayNum = Number(dayStr);
          isFirstOfMonth = dayNum === 1;
        } else {
          // After transformation it will be like "May 1"; detect standalone 1 at the end
          isFirstOfMonth = /\b1\b$/.test(raw);
        }

        if (isFirstOfMonth) {
          const x = Number(node.getAttribute('x')) || 0;
          // Find nearest month center to this day cell
          let nearest = months[0];
          for (let i = 1; i < months.length; i++) {
            if (Math.abs(months[i].x - x) < Math.abs(nearest.x - x)) nearest = months[i];
          }

          if (nearest && nearest.name && raw.includes(',')) {
            node.textContent = `${nearest.name} 1`;
          }
          node.style.fontWeight = '700';
        } else {
          node.style.fontWeight = '';
        }
      });
    } catch (_) {
      // no-op
    }
  }, [view]);

  // Observe calendar DOM changes to keep labels transformed
  useEffect(() => {
    if (!containerRef.current) return;
    const root = containerRef.current;
    const calendarGroup = root.querySelector('svg .calendar');
    if (!calendarGroup) return;

    updateCalendarHeaderLabels();

    const observer = new MutationObserver(() => {
      updateCalendarHeaderLabels();
    });
    observer.observe(calendarGroup, { childList: true, subtree: true, characterData: true });
    calendarMutationObserverRef.current = observer;
    return () => {
      try { observer.disconnect(); } catch (_) {}
      calendarMutationObserverRef.current = null;
    };
  }, [updateCalendarHeaderLabels, view]);

  // Convert our data format to gantt-task-react format
  // Chart column width: the setting, or a default per view mode
  const columnWidth = settings.columnWidth || (view === ViewMode.Day ? 60 : view === ViewMode.Week ? 200 : view === ViewMode.Month ? 160 : view === ViewMode.Year ? 360 : 90);

  // The chart draws bar labels in gantt-task-react's default font
  const measureLabel = useMemo(
    () => makeTextMeasurer('14px Arial, Roboto, Oxygen, Ubuntu, Cantarell, "Fira Sans", "Droid Sans", "Helvetica Neue"'),
    []
  );

  const ganttTasks = useMemo(() => {
    if (!data || !data.tasks) return [];

    // Defensive: normalize any incoming date-like values to Date or null
    const normalizeDate = (value) => {
      if (!value) return null;
      if (value instanceof Date) return isValidDate(value) ? value : null;
      const d = new Date(value);
      return isValidDate(d) ? d : null;
    };

    // Create a map of rowId to task id for dependency resolution
    const rowIdToTaskIdMap = new Map();
    data.tasks.forEach(task => {
      rowIdToTaskIdMap.set(String(task.rowId), task.id);
      if (task.recordId) rowIdToTaskIdMap.set(String(task.recordId), task.id);
    });

    return data.tasks.map(task => {
      const isExpanded = expandedTasks.has(task.id);
      const taskColor = getTaskColor(task.status, task.isOverdue, task.statusInfo);
      
      // Convert dependencies from rowIds to task ids
      const ganttDependencies = [];
      if (task.dependencies && task.dependencies.length > 0) {
        task.dependencies.forEach(depRowId => {
          const taskId = rowIdToTaskIdMap.get(String(depRowId));
          if (taskId) {
            ganttDependencies.push(taskId);
          }
        });
      }
      
      // Normalize dates and skip invalid
      const startDate = normalizeDate(task.start);
      const endDate = normalizeDate(task.end);
      if (!startDate || !endDate) return null;

      // Bar label: project name (the stage is in the list), shortened to fit inside the bar
      const fullName = task.name;
      let barLabel = task.isGroup || settings?.barLabel === 'name-stage' ? task.name : (task.baseName || task.name);
      if (settings?.fitBarLabels !== false) {
        const barPx = Math.max(0, (endDate.getTime() - startDate.getTime()) / 86400000) * pixelsPerDay(view, columnWidth);
        barLabel = fitBarLabel(barLabel, barPx, measureLabel);
      }

      return {
        id: task.id,
        name: barLabel,
        fullName,
        start: startDate,
        end: endDate,
        progress: task.progress,
        type: task.type,
        project: task.project,
        dependencies: ganttDependencies,
        // Clicking a group flips its default state, whichever way it started
        hideChildren: task.type === 'project' ? (Boolean(task.hideChildren) !== isExpanded) : undefined,
        // Solid = progress through release stages; tint = what's left
        styles: taskColor.startsWith('#')
          ? {
              backgroundColor: `${taskColor}40`,
              backgroundSelectedColor: `${taskColor}66`,
              progressColor: taskColor,
              progressSelectedColor: taskColor
            }
          : {
              backgroundColor: taskColor,
              backgroundSelectedColor: taskColor,
              progressColor: 'rgba(255, 255, 255, 0.7)',
              progressSelectedColor: 'rgba(255, 255, 255, 0.7)'
            },
        // Dragging only makes sense for rows backed by real date columns
        isDisabled: !!task.isGroup || !settings?.enableDragAndDrop,
        // Custom properties for our use
        statusInfo: task.statusInfo,
        stage: task.stage,
        group: task.group,
        dependsOn: task.dependsOn || [],
        blockedBy: task.blockedBy || [],
        brokenDependencies: task.brokenDependencies || [],
        isGroup: !!task.isGroup,
        childCount: task.childCount,
        baseName: task.baseName,
        assignee: task.assignee,
        status: task.status,
        details: task.details,
        isOverdue: task.isOverdue,
        parentTask: task.parentTask,
        rowId: task.rowId,
        recordId: task.recordId
      };
    }).filter(Boolean);
  }, [data, expandedTasks, settings?.enableDragAndDrop, settings?.barLabel, settings?.fitBarLabels, view, columnWidth, measureLabel]);

  const hasStages = useMemo(() => ganttTasks.some(t => t.stage), [ganttTasks]);
  const hasOwners = useMemo(() => ganttTasks.some(t => t.assignee), [ganttTasks]);

  // Helpers for modern task list styling
  const stringToHslColor = useCallback((input, s = 55, l = 60) => {
    if (!input) return `hsl(0, 0%, ${l}%)`;
    let hash = 0;
    for (let i = 0; i < input.length; i++) {
      // eslint-disable-next-line no-bitwise
      hash = input.charCodeAt(i) + ((hash << 5) - hash);
    }
    const hue = Math.abs(hash) % 360;
    return `hsl(${hue}, ${s}%, ${l}%)`;
  }, []);

  const getInitials = useCallback((name) => {
    if (!name) return '?';
    const parts = String(name).trim().split(/\s+/);
    const first = parts[0]?.[0] || '';
    const last = parts[1]?.[0] || '';
    return (first + last).toUpperCase() || first.toUpperCase() || '?';
  }, []);

  const StatusBadge = ({ status, statusInfo, isOverdue, isGroup }) => {
    if (isGroup) {
      return <div className="px-2 py-0.5 rounded-md text-xs font-medium border bg-muted text-muted-foreground border-border">{status}</div>;
    }
    const hasStatus = statusInfo && statusInfo.key && statusInfo.key !== 'unknown';
    if (isOverdue && !hasStatus) {
      return <div className="px-2 py-0.5 rounded-md text-xs font-medium border bg-destructive/10 text-destructive border-destructive/20">Overdue</div>;
    }
    const color = statusInfo?.color || '#94a3b8';
    return (
      <div
        className="px-2 py-0.5 rounded-md text-xs font-medium border truncate max-w-full"
        style={{ backgroundColor: `${color}1a`, color, borderColor: `${color}40` }}
        title={statusInfo?.label || status}
      >
        {statusInfo?.shortLabel || status || 'No status'}
      </div>
    );
  };

  const AssigneeAvatar = ({ name }) => {
    const bg = stringToHslColor(String(name || 'U'), 65, 48);
    return (
      <div
        className="w-6 h-6 rounded-full text-[10px] font-semibold flex items-center justify-center text-white shadow-sm"
        style={{ backgroundColor: bg }}
        aria-label={name || 'Assignee'}
        title={name || 'Unassigned'}
      >
        {getInitials(name || 'U')}
      </div>
    );
  };

  // Handle task selection
  const handleTaskClick = useCallback((task) => {
    // Ignore click events that happen immediately after a drag
    const now = Date.now();
    if (now - lastDragTimeRef.current < 300) {
      return;
    }
    setSelectedTask(task.id);
    if (settings?.enableTaskClick && onTaskClick) {
      onTaskClick(task);
    }
  }, [onTaskClick, settings?.enableTaskClick]);

  // Handle task selection change
  const handleTaskSelect = useCallback((task, isSelected) => {
    if (isSelected) {
      setSelectedTask(task.id);
    } else {
      setSelectedTask(null);
    }
    
    if (onTaskSelect) {
      onTaskSelect(task, isSelected);
    }
  }, [onTaskSelect]);

  // Handle expander click for hierarchical tasks
  const handleExpanderClick = useCallback((task) => {
    const newExpandedTasks = new Set(expandedTasks);
    
    if (expandedTasks.has(task.id)) {
      newExpandedTasks.delete(task.id);
    } else {
      newExpandedTasks.add(task.id);
    }
    
    setExpandedTasks(newExpandedTasks);
    
    if (onExpanderClick) {
      onExpanderClick(task);
    }
  }, [expandedTasks, onExpanderClick]);

  // Handle date changes for tasks
  const handleDateChange = useCallback((task, _children) => {
    // gantt-task-react calls this with (task, children): the new dates are on the
    // task itself, not in separate arguments
    // Drags move in minutes; snap to whole days so a write-back never lands on the wrong day
    const newStart = task.start && snapToDay(task.start);
    const newEnd = task.end && snapToDay(task.end);

    // The library can report a single drag twice. Ignore an identical repeat so
    // the Update Task action (and the audit log) only fire once per drag.
    const now = Date.now();
    const key = `${task.id}|${newStart && newStart.getTime()}|${newEnd && newEnd.getTime()}`;
    if (lastDateChangeRef.current.key === key && now - lastDateChangeRef.current.time < 1000) {
      return;
    }
    lastDateChangeRef.current = { key, time: now };

    // Mark the time a drag action completed
    lastDragTimeRef.current = now;
    if (onDateChange) {
      onDateChange(task, newStart, newEnd);
    }
  }, [onDateChange]);

  // Custom tooltip content with shadcn/ui styling
  const TaskTooltip = ({ task, fontSize, fontFamily }) => {
    if (!task) return null;
    const fmt = (d) => (d && isValidDate(d) ? format(d, settings?.dateFormat || 'MMM dd, yyyy') : '-');
    const Row = ({ label, children }) => (
      <div className="flex justify-between items-start gap-4">
        <span className="text-muted-foreground shrink-0">{label}</span>
        <span className="font-medium text-popover-foreground text-right">{children}</span>
      </div>
    );
    const KeyList = ({ label, ids, tone }) => (ids && ids.length > 0 ? (
      <div className="mt-2">
        <div className={`text-xs mb-1 ${tone || 'text-muted-foreground'}`}>{label}</div>
        {ids.map(id => <div key={id} className="text-xs text-popover-foreground">{id}</div>)}
      </div>
    ) : null);

    return (
      <div className="bg-popover border border-border rounded-md shadow-lg p-4 max-w-sm" style={{ fontSize, fontFamily }}>
        <div className="font-semibold text-popover-foreground mb-3">{task.isGroup ? task.name : (task.baseName || task.name)}</div>
        <div className="space-y-2 text-sm">
          {!task.isGroup && (
            <Row label="Status">
              <span style={{ color: task.statusInfo?.color }}>{task.statusInfo?.label || task.status}</span>
              {task.isOverdue && <span className="text-destructive"> · Overdue</span>}
            </Row>
          )}
          {task.stage && <Row label="Stage">{task.stage}</Row>}
          {task.group && !task.isGroup && <Row label="Group">{task.group}</Row>}
          {task.isGroup && <Row label="Items">{task.childCount}</Row>}
          <Row label="Start">{fmt(task.start)}</Row>
          <Row label="End">{fmt(task.end)}</Row>
          {task.assignee && <Row label="Owner">{task.assignee}</Row>}
          {task.details && (
            <div className="mt-3 pt-3 border-t border-border">
              <div className="text-muted-foreground text-xs mb-1">Details</div>
              <div className="text-popover-foreground text-xs">{task.details}</div>
            </div>
          )}
          <KeyList label="Blocked by" ids={task.blockedBy} tone="text-destructive" />
          <KeyList label="Depends on" ids={(task.dependsOn || []).filter(id => !(task.blockedBy || []).includes(id))} />
          <KeyList label="Not in this view (filtered out or renamed)" ids={task.brokenDependencies} tone="text-amber-600" />
        </div>
      </div>
    );
  };

  // Date aggregation is now controlled via Settings; legend removed

  // Width of the frozen task list. The custom list below ignores gantt-task-react's
  // own cell width, so this is applied to the list itself.
  const listWidth = Math.min(1000, Math.max(240, Number(settings.taskListWidth) || 440));

  // Gantt configuration with shadcn/ui colors
  const ganttConfig = {
    columnWidth,
    listCellWidth: `${listWidth}px`,
    rowHeight: settings.rowHeight || 50,
    // Make bars slightly thinner and more rounded by default
    barFill: settings.barFill || 50,
    barCornerRadius: settings.barCornerRadius || 5,
    // Slimmer calendar/date header height for a more modern single-row look
    headerHeight: 32,
    ganttHeight: availableHeight ?? settings.ganttHeight ?? 400,
    barBackgroundColor: settings.barBackgroundColor || 'hsl(var(--muted))',
    barBackgroundSelectedColor: settings.barBackgroundSelectedColor || 'hsl(var(--accent))',
    barProgressColor: settings.barProgressColor || 'rgba(255, 255, 255, 0.7)',
    barProgressSelectedColor: settings.barProgressSelectedColor || 'rgba(255, 255, 255, 0.7)',
    projectProgressColor: settings.projectProgressColor || 'rgba(255, 255, 255, 0.7)',
    projectProgressSelectedColor: settings.projectProgressSelectedColor || 'rgba(255, 255, 255, 0.7)',
    milestoneBackgroundColor: settings.milestoneBackgroundColor || 'hsl(var(--accent))',
    milestoneBackgroundSelectedColor: settings.milestoneBackgroundSelectedColor || 'hsl(var(--accent))',
    arrowColor: settings.arrowColor || 'hsl(var(--muted-foreground))',
    arrowIndent: settings.arrowIndent || 20,
    todayColor: settings.todayColor || 'hsl(var(--accent))',
    viewMode: view,
    locale: settings.locale || 'en-US'
  };

  if (!data || !data.tasks || data.tasks.length === 0) {
    return (
      <div className="flex items-center justify-center h-64 bg-muted/50 rounded-lg border border-border">
        <div className="text-center">
          <div className="text-muted-foreground text-lg font-medium">No tasks to display</div>
          <div className="text-muted-foreground/70 text-sm mt-1">
            {data?.skipped?.noDates > 0
              ? `${data.skipped.noDates} row${data.skipped.noDates === 1 ? ' has' : 's have'} no start or end date. Fill in Start Date and End Date to see them here.`
              : 'Configure your data source and columns to get started'}
          </div>
        </div>
      </div>
    );
  }

  return (
      <div ref={containerRef} className="gantt-container w-full h-full" data-view={view}>
        <div className="gantt-chart-wrapper h-full border border-border rounded-lg overflow-hidden bg-background">
        <Gantt
          tasks={ganttTasks}
          viewMode={view}
          listCellWidth={ganttConfig.listCellWidth}
          columnWidth={ganttConfig.columnWidth}
          headerHeight={ganttConfig.headerHeight}
          rowHeight={ganttConfig.rowHeight}
          barFill={ganttConfig.barFill}
          barCornerRadius={ganttConfig.barCornerRadius}
          ganttHeight={ganttConfig.ganttHeight}
          barBackgroundColor={ganttConfig.barBackgroundColor}
          barBackgroundSelectedColor={ganttConfig.barBackgroundSelectedColor}
          barProgressColor={ganttConfig.barProgressColor}
          barProgressSelectedColor={ganttConfig.barProgressSelectedColor}
          projectProgressColor={ganttConfig.projectProgressColor}
          projectProgressSelectedColor={ganttConfig.projectProgressSelectedColor}
          milestoneBackgroundColor={ganttConfig.milestoneBackgroundColor}
          milestoneBackgroundSelectedColor={ganttConfig.milestoneBackgroundSelectedColor}
          arrowColor={ganttConfig.arrowColor}
          arrowIndent={ganttConfig.arrowIndent}
          todayColor={ganttConfig.todayColor}
          locale={ganttConfig.locale}
          onSelect={handleTaskSelect}
          onExpanderClick={handleExpanderClick}
          onClick={handleTaskClick}
          onDateChange={handleDateChange}
          allowTaskDrag={true}
          TooltipContent={TaskTooltip}
            TaskListHeader={() => (
              <div className="task-list-header bg-muted/70 backdrop-blur border-b border-border px-4 text-xs uppercase tracking-wide text-muted-foreground flex items-center justify-between gap-3" style={{ height: ganttConfig.headerHeight, width: listWidth }}>
                <div className="flex-1 min-w-0">{hasStages ? 'Project · Stage' : 'Task / Project'}</div>
                {hasOwners && <div className="w-16 shrink-0 text-center">Owner</div>}
                <div className="w-[88px] shrink-0 text-center">Status</div>
                <div className="w-[88px] shrink-0 text-center">{hasStages ? 'Stage' : 'Progress'}</div>
              </div>
            )}
          TaskListTable={(props) => (
              <div className="task-list-table" style={{ width: listWidth }}>
                {props.tasks.map((task) => {
                  const progressPercent = Math.round(Number(task.progress || 0));
                  const isBlocked = (task.blockedBy || []).length > 0;
                  return (
                    <div
                      key={task.id}
                      className={`task-list-row flex items-center gap-3 px-4 py-2 border-b border-border hover:bg-muted/50 cursor-pointer transition-colors ${
                        selectedTask === task.id ? 'bg-accent/50' : ''
                      } ${task.isGroup ? 'bg-muted/40' : ''}`}
                      style={{ height: ganttConfig.rowHeight }}
                      onClick={() => (task.isGroup ? handleExpanderClick(task) : handleTaskClick(task))}
                    >
                      <div className={`flex-1 min-w-0 flex items-center gap-2 ${task.project ? 'pl-4' : ''}`}>
                        {task.isGroup && (
                          <span className="text-muted-foreground text-xs w-3">{task.hideChildren ? '▸' : '▾'}</span>
                        )}
                        <div className="min-w-0">
                          <div className={`text-foreground truncate ${task.isGroup ? 'font-semibold' : 'font-medium'}`} title={task.name}>
                            {isBlocked && <span className="text-destructive mr-1" title="Blocked">⛔</span>}
                            {task.isGroup ? task.name : (task.baseName || task.name)}
                          </div>
                          {!task.isGroup && task.isOverdue && task.statusInfo && task.statusInfo.key !== 'unknown' && (
                            <div className="text-[10px] text-destructive truncate">
                              Overdue · ended {task.end && isValidDate(task.end) ? format(task.end, 'MMM d') : ''}
                            </div>
                          )}
                        </div>
                      </div>

                      {hasOwners && (
                        <div className="w-16 shrink-0 flex items-center justify-center">
                          {!task.isGroup && <AssigneeAvatar name={task.assignee} />}
                        </div>
                      )}

                      <div className="w-[88px] shrink-0 flex items-center justify-center">
                        <StatusBadge status={task.status} statusInfo={task.statusInfo} isOverdue={task.isOverdue} isGroup={task.isGroup} />
                      </div>

                      <div className="w-[88px] shrink-0">
                        <div className="h-2 rounded-full bg-muted overflow-hidden">
                          <div className="h-full rounded-full bg-primary transition-all" style={{ width: `${progressPercent}%` }} />
                        </div>
                        <div className="text-[10px] text-muted-foreground text-center mt-1 truncate">
                          {hasStages ? (task.isGroup ? `${progressPercent}% avg` : (task.stage || '—')) : `${progressPercent}%`}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
        />
      </div>
    </div>
  );
};

export default GanttChart; 