import { format } from 'date-fns';

/**
 * Sigma date columns arrive as timestamps (e.g. 2026-09-01T07:00:00.000Z for a
 * date stored at midnight Pacific). The calendar day is the UTC date of that
 * value, so build a local-midnight Date from it. Every viewer then sees the
 * same calendar day regardless of their timezone.
 */
export function toCalendarDate(d) {
  return new Date(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
}

/** Round a dragged Date to the nearest whole local day (drags move in minutes). */
export function snapToDay(d) {
  const day = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  if (d.getHours() >= 12) day.setDate(day.getDate() + 1);
  return day;
}

/** Local calendar day as YYYY-MM-DD, the format Sigma date variables expect. */
export function toDateString(value) {
  const d = value instanceof Date ? value : new Date(value);
  return Number.isNaN(d.getTime()) ? null : format(d, 'yyyy-MM-dd');
}
