import { parseISO, isValid, isBefore, isAfter } from 'date-fns';
import { normalizeStatus, stageProgress, resolveDependencyIds } from './roadmap';
import { toCalendarDate } from './dates';

/**
 * Process Sigma data into Gantt chart structure
 * @param {Object} sigmaData - Sigma data object with column arrays
 * @param {Object} config - Configuration object with column names
 * @param {Object} settings - Settings object
 * @param {Object} elementColumns - Column information from getElementColumns
 * @returns {Object} - { tasks, dependencies } or null if no valid data
 */
export function processGanttData(sigmaData, config, settings, elementColumns) {
  if (!sigmaData || !config.taskName || !config.startDate || !config.endDate || !elementColumns) {
    return null;
  }

  const col = (key) => (config[key] ? (sigmaData[config[key]] || []) : []);
  const taskNameData = col('taskName');
  const startDateData = col('startDate');
  const endDateData = col('endDate');
  const assigneeData = col('assignee');
  const statusData = col('status');
  const progressData = col('progress');
  const parentTaskData = col('parentTask');
  const dependenciesData = col('dependencies');
  const blockedByData = col('blockedBy');
  const detailsData = col('details');
  const idData = col('ID');
  const stageData = col('stage');
  const groupByData = col('groupBy');
  const keyColumnIds = Array.isArray(config.keyColumns)
    ? config.keyColumns
    : [config.keyColumns].filter(Boolean);
  const keyColumnData = keyColumnIds.map(id => sigmaData[id] || []);
  const keySeparator = settings.keySeparator ?? ' · ';
  const excluded = new Set(settings.excludeStatuses || []);

  if (taskNameData.length === 0) {
    return null;
  }

  const dataLength = taskNameData.length;
  const tasks = [];
  const today = new Date();
  // Rows that can't be drawn, counted so the plugin can say so instead of
  // silently showing a shorter list
  const skipped = { noName: 0, noDates: 0, invalidRange: 0 };

  for (let i = 0; i < dataLength; i++) {
    const taskName = taskNameData[i];
    if (!taskName) {
      skipped.noName++;
      continue;
    }

    // Only real Start Date / End Date values are drawn
    const startDate = parseDate(startDateData[i]);
    const endDate = parseDate(endDateData[i]);
    if (!startDate || !endDate) {
      skipped.noDates++;
      continue;
    }
    if (isAfter(startDate, endDate)) {
      skipped.invalidRange++;
      continue;
    }

    const statusInfo = normalizeStatus(statusData[i], settings);
    if (excluded.has(statusInfo.key)) continue;

    const stage = stageData[i] ? String(stageData[i]) : '';
    const progressFromColumn = config.progress ? parseProgress(progressData[i]) : null;
    const progressFromStage = stageProgress(stage, settings.stageOrder);
    const progress = progressFromColumn ?? progressFromStage ?? (statusInfo.done ? 100 : 0);

    // Row identity: explicit ID column, else a key built from key columns
    // (matches the workbook's "Team · Project · Stage" dependency keys)
    // recordId is the row's own id (sent to the Selected ID control); rowId is
    // what dependency cells refer to. Key columns win for dependencies, so
    // mapping both an ID column and Key Columns works.
    const recordId = (config.ID && idData[i] !== null && idData[i] !== undefined && idData[i] !== '')
      ? String(idData[i])
      : null;
    let keyId = null;
    if (keyColumnData.length > 0) {
      const parts = keyColumnData.map(arr => arr[i]);
      if (parts.every(p => p !== null && p !== undefined && p !== '')) {
        keyId = parts.map(String).join(keySeparator);
      }
    }
    const rowId = keyId ?? recordId ?? `row-${i}`;

    const isOverdue = settings.showOverdue !== false
      && !statusInfo.done && !statusInfo.inactive
      && isBefore(endDate, today);

    const baseName = String(taskName);
    const name = stage && settings.appendStageToName !== false ? `${baseName} · ${stage}` : baseName;

    tasks.push({
      id: i.toString(),
      rowId,
      recordId,
      name,
      baseName,
      start: startDate,
      end: endDate,
      progress,
      stage,
      type: 'task',
      assignee: assigneeData[i] ? String(assigneeData[i]) : '',
      status: statusInfo.label,
      statusInfo,
      parentTask: parentTaskData[i] ? String(parentTaskData[i]) : null,
      group: groupByData[i] ? String(groupByData[i]) : (config.groupBy ? 'No group' : null),
      details: detailsData[i] ? String(detailsData[i]) : '',
      isOverdue,
      dependencyRaw: dependenciesData[i],
      blockedByRaw: blockedByData[i],
      originalIndex: i
    });
  }

  // Resolve dependency cells against the ids actually present
  const knownIds = new Set();
  tasks.forEach(t => {
    knownIds.add(t.rowId);
    if (t.recordId) knownIds.add(t.recordId);
  });
  const delimiter = settings.dependencyDelimiter || 'auto';
  tasks.forEach(task => {
    const deps = resolveDependencyIds(task.dependencyRaw, knownIds, delimiter);
    const blockers = resolveDependencyIds(task.blockedByRaw, knownIds, delimiter);
    task.dependsOn = deps;
    task.blockedBy = blockers;
    task.dependencies = Array.from(new Set([...deps, ...blockers]));
    task.brokenDependencies = task.dependencies.filter(id => !knownIds.has(id));
    delete task.dependencyRaw;
    delete task.blockedByRaw;
  });

  const sortedTasks = sortTasks(tasks, settings);
  const withHierarchy = config.groupBy
    ? buildGroupedHierarchy(sortedTasks, settings)
    : buildTaskHierarchy(sortedTasks);

  return {
    tasks: withHierarchy,
    dependencies: [],
    skipped
  };
}

/**
 * Human-readable note about rows that were left out, or '' when none were.
 * Rows hidden on purpose (e.g. Dropped via excludeStatuses) are not counted.
 */
export function describeSkipped(skipped) {
  if (!skipped) return '';
  const parts = [];
  if (skipped.noDates > 0) parts.push(`${skipped.noDates} without a start or end date`);
  if (skipped.invalidRange > 0) parts.push(`${skipped.invalidRange} with a start date after the end date`);
  if (skipped.noName > 0) parts.push(`${skipped.noName} without a name`);
  return parts.length ? `Not shown: ${parts.join(', ')}.` : '';
}

/**
 * Synthesize one parent bar per group value (e.g. Team), spanning its
 * children. Avoids the classic hierarchy's need for a separate parent row
 * whose name matches exactly.
 */
function buildGroupedHierarchy(tasks, settings) {
  const groups = new Map();
  tasks.forEach(task => {
    const key = task.group || 'No group';
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(task);
  });
  const groupKeys = Array.from(groups.keys()).sort((a, b) => a.localeCompare(b));
  const result = [];
  groupKeys.forEach(key => {
    const children = groups.get(key);
    const groupId = `group::${key}`;
    const start = new Date(Math.min(...children.map(c => c.start.getTime())));
    const end = new Date(Math.max(...children.map(c => c.end.getTime())));
    const blockedCount = children.filter(c => c.statusInfo.key === 'blocked').length;
    result.push({
      id: groupId,
      rowId: groupId,
      name: key,
      baseName: key,
      start,
      end,
      progress: Math.round(children.reduce((s, c) => s + (c.progress || 0), 0) / children.length),
      stage: '',
      type: 'project',
      assignee: '',
      status: `${children.length} item${children.length === 1 ? '' : 's'}`,
      statusInfo: { ...normalizeStatus(null, settings), label: `${children.length} items`, color: '#64748b' },
      details: blockedCount ? `${blockedCount} blocked` : '',
      isOverdue: false,
      isGroup: true,
      dependsOn: [],
      blockedBy: [],
      dependencies: [],
      brokenDependencies: [],
      hideChildren: settings.expandAll === false,
      childCount: children.length
    });
    children.forEach(child => result.push({ ...child, project: groupId }));
  });
  return result;
}

/**
 * Parse date from various formats
 * @param {any} dateValue - Date value to parse
 * @returns {Date|null} - Parsed date or null if invalid
 */
function parseDate(dateValue) {
  if (!dateValue) return null;

  // Already a Date object
  if (dateValue instanceof Date) {
    return isValid(dateValue) ? toCalendarDate(dateValue) : null;
  }

  if (typeof dateValue === 'string') {
    const text = dateValue.trim();
    // A bare YYYY-MM-DD is already a calendar day
    if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
      const day = parseISO(text);
      return isValid(day) ? day : null;
    }
    // Timestamps carry a time zone offset; keep their calendar day
    const isoDate = parseISO(text);
    if (isValid(isoDate)) return toCalendarDate(isoDate);
    const standardDate = new Date(text);
    if (isValid(standardDate)) return toCalendarDate(standardDate);
  }

  // Numeric timestamp (seconds or milliseconds)
  if (typeof dateValue === 'number') {
    const ms = dateValue < 10000000000 ? dateValue * 1000 : dateValue;
    const timestampDate = new Date(ms);
    if (isValid(timestampDate)) return toCalendarDate(timestampDate);
  }

  return null;
}

/**
 * Parse progress value from various formats
 * @param {any} progressValue - Progress value to parse
 * @returns {number} - Progress percentage (0-100)
 */
function parseProgress(progressValue) {
  if (progressValue === null || progressValue === undefined || progressValue === '') {
    return 0; // Default to 0 if no progress value provided
  }

  // If it's already a number
  if (typeof progressValue === 'number') {
    return Math.max(0, Math.min(100, progressValue)); // Clamp between 0-100
  }

  // If it's a string, try to parse as number
  if (typeof progressValue === 'string') {
    const parsed = parseFloat(progressValue);
    if (!isNaN(parsed)) {
      return Math.max(0, Math.min(100, parsed)); // Clamp between 0-100
    }
  }

  return 0; // Default to 0 if parsing fails
}

/**
 * Build task hierarchy for project-task relationships
 * @param {Array} tasks - Array of tasks
 * @returns {Array} - Tasks with hierarchy information
 */
function buildTaskHierarchy(tasks) {
  const taskMap = new Map();
  tasks.forEach(task => {
    taskMap.set(task.baseName || task.name, task);
  });

  // First, identify which tasks are projects (have children)
  const projectTaskNames = new Set();
  tasks.forEach(task => {
    if (task.parentTask) {
      projectTaskNames.add(task.parentTask);
    }
  });

  return tasks.map(task => {
    if (task.parentTask) {
      // This is a child task
      const parent = taskMap.get(task.parentTask);
      if (parent) {
        return {
          ...task,
          type: 'task',
          project: parent.id,
          hideChildren: false
        };
      }
    }
    
    // Check if this task is a project (has children)
    if (projectTaskNames.has(task.baseName || task.name)) {
      return {
        ...task,
        type: 'project',
        progress: 100, // Projects typically show as fully filled bars
        hideChildren: false
      };
    }
    
    // This is a standalone task
    return {
      ...task,
      type: 'task',
      hideChildren: false
    };
  });
}



/**
 * Sort tasks based on settings
 * @param {Array} tasks - Array of tasks
 * @param {Object} settings - Settings object
 * @returns {Array} - Sorted tasks
 */
function sortTasks(tasks, settings) {
  if (!settings.enableSorting) return tasks;

  const sortedTasks = [...tasks];

  sortedTasks.sort((a, b) => {
    let compareValue = 0;

    switch (settings.sortBy) {
      case 'name':
        compareValue = a.name.localeCompare(b.name);
        break;
      case 'startDate':
        compareValue = a.start.getTime() - b.start.getTime();
        break;
      case 'endDate':
        compareValue = a.end.getTime() - b.end.getTime();
        break;
      case 'status':
        compareValue = (a.statusInfo?.rank ?? 99) - (b.statusInfo?.rank ?? 99)
          || a.start.getTime() - b.start.getTime();
        break;
      case 'stage': {
        const order = (settings.stageOrder || []).map(s => String(s).toLowerCase());
        const ai = order.indexOf(String(a.stage || '').toLowerCase());
        const bi = order.indexOf(String(b.stage || '').toLowerCase());
        compareValue = (ai < 0 ? 99 : ai) - (bi < 0 ? 99 : bi);
        break;
      }
      case 'assignee':
        compareValue = a.assignee.localeCompare(b.assignee);
        break;
      default:
        compareValue = a.originalIndex - b.originalIndex;
    }

    return settings.sortDirection === 'desc' ? -compareValue : compareValue;
  });

  return sortedTasks;
}

/**
 * Get color for task based on status using shadcn/ui color system
 * Colors are chosen to have good contrast with white text
 * @param {string} status - Task status
 * @param {boolean} isOverdue - Whether task is overdue
 * @returns {string} - CSS color value using shadcn/ui variables
 */
export function getTaskColor(status, isOverdue, statusInfo) {
  // A recognized status keeps its own color; overdue only takes over the bar
  // when there is no status to show (generic task data)
  const hasStatus = statusInfo && statusInfo.key && statusInfo.key !== 'unknown';
  if (isOverdue && !hasStatus) return 'hsl(var(--destructive))'; // Destructive color for overdue (red)
  if (statusInfo && statusInfo.color) return statusInfo.color;

  const statusLower = status.toLowerCase();
  switch (statusLower) {
    case 'completed':
      return 'hsl(142 71% 45%)'; // Green with good contrast for white text
    case 'in progress':
      return 'hsl(var(--primary))'; // Primary color (blue)
    case 'blocked':
      return 'hsl(25 95% 53%)'; // Orange-500 equivalent
    case 'not started':
    default:
      return 'hsl(215 16% 47%)'; // Muted slate color with better contrast for white text
  }
}

/**
 * Validate gantt configuration
 * @param {Object} config - Configuration object
 * @returns {Object} - { isValid, errors }
 */
export function validateGanttConfig(config) {
  const errors = [];

  if (!config.source) {
    errors.push('Data source is required');
  }

  if (!config.taskName) {
    errors.push('Task Name column is required');
  }

  if (!config.startDate) {
    errors.push('Start Date column is required');
  }

  if (!config.endDate) {
    errors.push('End Date column is required');
  }

  return {
    isValid: errors.length === 0,
    errors
  };
}

/**
 * Get column name from element columns
 * @param {Object} elementColumns - Element columns object
 * @param {string} columnKey - Column key
 * @returns {string} - Column name
 */
export function getColumnName(elementColumns, columnKey) {
  if (!elementColumns || !columnKey) return columnKey;
  const column = elementColumns[columnKey];
  return column ? column.name : columnKey;
}

/**
 * Validate required columns exist
 * @param {Object} elementColumns - Element columns object
 * @param {Array} requiredColumns - Array of required column keys
 * @returns {Object} - { isValid, missingColumns }
 */
export function validateRequiredColumns(elementColumns, requiredColumns) {
  const missingColumns = [];
  
  requiredColumns.forEach(columnKey => {
    if (!elementColumns[columnKey]) {
      missingColumns.push(columnKey);
    }
  });

  return {
    isValid: missingColumns.length === 0,
    missingColumns
  };
} 