// How many days one chart column spans in each view mode (matches gantt-task-react's layout)
const DAYS_PER_COLUMN = {
  'Hour': 1 / 24,
  'Quarter Day': 0.25,
  'Half Day': 0.5,
  'Day': 1,
  'Week': 7,
  'Month': 30.44,
  'Year': 365.25
};

export function pixelsPerDay(viewMode, columnWidth) {
  return columnWidth / (DAYS_PER_COLUMN[viewMode] || 1);
}

/**
 * Returns a function that gives a string's rendered width in px for a CSS font.
 * Uses a canvas for exact widths; where no canvas is available it falls back
 * to an average glyph width.
 */
export function makeTextMeasurer(font, fallbackCharPx = 7) {
  let ctx = null;
  try {
    if (typeof document !== 'undefined') {
      const canvas = document.createElement('canvas');
      const maybe = canvas.getContext && canvas.getContext('2d');
      if (maybe && typeof maybe.measureText === 'function') {
        maybe.font = font;
        ctx = maybe;
      }
    }
  } catch (_) {
    ctx = null;
  }
  return (text) => (ctx ? ctx.measureText(String(text)).width : String(text).length * fallbackCharPx);
}

/**
 * gantt-task-react prints a bar's label inside the bar only when the text is
 * narrower than the bar, otherwise beside it. Shorten the label so it stays
 * inside whenever the bar can hold a readable amount of text, and leave labels
 * that already fit alone. A bar too small for that keeps its full label, which
 * the chart then shows next to the bar.
 */
export function fitBarLabel(text, barPx, measure, { padding = 12, minChars = 8 } = {}) {
  const label = String(text ?? '');
  const room = barPx - padding;
  if (measure(label) <= room) return label;

  // longest prefix that still fits with the ellipsis
  let lo = 0;
  let hi = label.length;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (measure(label.slice(0, mid).trimEnd() + '…') <= room) lo = mid;
    else hi = mid - 1;
  }
  if (lo >= minChars) return label.slice(0, lo).trimEnd() + '…';
  return label;
}
